html:
{% set print_style = frappe.db.get_single_value("Print Settings", "print_style") %}
{% set color = frappe.db.get_value("Print Style", print_style, "custom_color") %}

{# ----------------------------------------------------------------------- #}
{# Exchange rate now comes directly from Purchase Order (no Currency Exchange) #}
{# ----------------------------------------------------------------------- #}
{% set exchange_rate = doc.conversion_rate or 1 %}
{% set company_currency = frappe.db.get_value("Company", doc.company, "default_currency") %}

<style>
    .pf-color { color: {{ color }}; }
    .pf-box { border: 1px solid {{ color }}; padding: 10px !important; }
    .pf-row { border-bottom: 1px solid {{ color }}; padding: 8px 0 !important; }
    .pf-label { font-weight: bold; color: {{ color }}; font-size: 12px; }
    .pf-value { font-size: 12px; padding-top: 3px !important; }
    .print-format td { padding: 5px 4px !important; }
</style>


<div class="pf-font">

    {% if letter_head %}
    {{ letter_head }}
    {% endif %}

    <style>
        .title-h3 {
            font-size: 16px;
            margin: 0;
            padding: 0;
            text-align: left !important;
        }

        .pf-label {
            font-weight: bold;
        }

        .pf-value {
            display: block;
            font-weight: normal;
        }
    </style>

    <table class="pf-font-size" style="width: 100%; line-height: 1; border:1px solid {{ color }}; border-collapse: collapse;">
        <tr>
            <!-- H3 title on the left -->
            <td>
                <h3 class="pf-heading pf-color title-h3">
                    {{ doc.doctype }}
                </h3>
            </td>

            <!-- PO # stacked -->
            <td style="white-space:nowrap; padding-right:15px; text-align:right; vertical-align: top;">
                <div class="pf-label">PO # رقم الطلب</div>
                <div class="pf-value">{{ doc.name }}</div>
            </td>

            <!-- Request Date stacked -->
            <td style="white-space:nowrap; text-align:right; vertical-align: top;">
                <div class="pf-label">Request Date تاريخ الطلب</div>
                <div class="pf-value">{{ doc.get_formatted("transaction_date") }}</div>
            </td>
        </tr>
    </table>

    <table class="pf-font-size" style="width: 100%; line-height: 1;">
        <tbody>

        <tr>
            <!-- LEFT SIDE -->
            <td style="width: 50%; vertical-align: top;">
            </td>

            <!-- RIGHT SIDE -->
            <td style="width: 50%; vertical-align: top;">
            </td>
        </tr>

        </tbody>
    </table>




    <!-- ======================================================================= -->
    <!-- ======================= SUPPLIER INFORMATION BOX ======================= -->
    <!-- ======================================================================= -->

    {% set supplier = doc.supplier %}
    {% set addr = frappe.db.get_value("Dynamic Link",
        {"link_name": supplier, "link_doctype": "Supplier", "parenttype": "Address"},
        "parent"
    ) %}

    {% if addr %}
        {% set address = frappe.get_doc("Address", addr) %}
    {% endif %}

    {% set cont = frappe.db.get_value("Dynamic Link",
        {"link_name": supplier, "link_doctype": "Supplier", "parenttype": "Contact"},
        "parent"
    ) %}

    {% if cont %}
        {% set contact = frappe.get_doc("Contact", cont) %}
    {% endif %}

    <table style="width:100%; border-collapse:collapse; margin-bottom:15px !important;">

        <tr>

            <!-- LEFT SIDE SUPPLIER BLOCK -->
            <td class="pf-box" style="width:50%; vertical-align:top;">

                <p class="pf-label">To,</p>

                <p class="pf-value" style="margin-bottom:8px !important;">
                    <b>{{ doc.supplier_name }}</b>
                </p>

                {% if address %}

                    {% if address.address_title %}
                        <p class="pf-value">{{ address.address_title }}</p>
                    {% endif %}

                    {% if address.city or address.address_line1 %}
                        <p class="pf-value">{{ address.city or "" }}, {{ address.address_line1 or "" }},</p>
                    {% endif %}

                    {% if address.address_line2 or address.country %}
                        <p class="pf-value">{{ address.address_line2 or "" }} {{ address.country or "" }}</p>
                    {% endif %}

                    {% if address.phone or address.fax %}
                        <p class="pf-value">
                            {% if address.phone %}Tel: {{ address.phone }}{% endif %}
                            {% if address.fax %} , Fax: {{ address.fax }}{% endif %}
                        </p>
                    {% endif %}
                {% endif %}

                {% if contact %}
                    <p class="pf-value">
                        {{ contact.salutation or "" }} {{ contact.first_name or "" }} {{ contact.middle_name or "" }} {{ contact.last_name or "" }}
                        {% if contact.mobile_no %} (Mob : {{ contact.mobile_no }}){% endif %}
                    </p>
                {% endif %}

            </td>

            <!-- RIGHT SIDE DISPATCH BOX -->
            <td class="pf-box" style="width:50%; vertical-align:top;">
                <!-- Dispatch Through -->
                <p class="pf-label">Dispatch Through</p>
                <p class="pf-value" style="margin-bottom:10px !important;">
                    {{ doc.custom_dispatch_through or "" }}
                </p>
                <hr style="border:0; border-top:1px solid {{ color }}; margin:10px 0 !important;">

                <!-- Destination -->
                <p class="pf-label">Destination</p>
                <p class="pf-value" style="margin-bottom:10px !important;">
                    {{ doc.shipping_address }}
                </p>

                {# --------------------------------------------------------------- #}
                {# Advance Payment: first Payment Entry linked to this Purchase Order #}
                {# --------------------------------------------------------------- #}
                <p class="pf-label">Advance Payment</p>

                {% set advance_paid = 0 %}
                {% set pe_rows = frappe.db.sql("""
                    SELECT pe.name, pe.paid_amount
                    FROM `tabPayment Entry Reference` per
                    INNER JOIN `tabPayment Entry` pe ON pe.name = per.parent
                    WHERE per.reference_doctype = 'Purchase Order'
                      AND per.reference_name = %s
                      AND pe.docstatus = 1
                    ORDER BY pe.posting_date ASC, pe.creation ASC
                    LIMIT 1
                """, (doc.name,), as_dict=1) %}

                {% if pe_rows and pe_rows|length > 0 %}
                    {% set advance_paid = pe_rows[0].paid_amount or 0 %}
                {% endif %}

                    <p class="pf-value">
                        {# paid_amount is coming from Payment Entry (company currency in your case) #}
                        {{ frappe.utils.fmt_money(advance_paid, currency=company_currency) }}
                    
                        {% if company_currency and doc.currency and company_currency != doc.currency %}
                            {% set rate = exchange_rate or 1 %}
                            &nbsp; ({{ frappe.utils.fmt_money(advance_paid / rate, currency=doc.currency) }})
                        {% endif %}
                    </p>

            </td>

        </tr>
    </table>

    {# ---------------- Precompute item + UOM breakdown ---------------- #}
    {% set items_map = {} %}
    {% set uom_totals = {} %}

    {% for it in doc.items %}
        {% set key = it.item_code %}

        {% if key not in items_map %}
            {% set _ = items_map.update({
                key: {
                    "item_name": it.item_name,
                    "uoms": {}
                }
            }) %}
        {% endif %}

        {% set current = items_map[key]["uoms"].get(it.uom, 0) + it.qty %}
        {% set _ = items_map[key]["uoms"].update({ it.uom: current }) %}

        {% set _ = uom_totals.update({
            it.uom: uom_totals.get(it.uom, 0) + it.qty
        }) %}
    {% endfor %}

    <table class="pf-item-table pf-font-size" style="border: 3px solid {{ color }};">
        <thead>
        <tr style="background-color: {{ color }};">
            <th style="width: 5%;">No.<br>م</th>
            <th style="width: 25%;">Pieces<br>Barcode</th>
            <th style="width: 50%;">Product<br>المنتج</th>
            <th style="width: 20%;">QTY / UOM<br>الكمية / الوحدة</th>
        </tr>
        </thead>
        <tbody>

        {% set idx = 1 %}
        {% for item_code, data in items_map.items() %}
            <tr style="border: 3px solid {{ color }};">
                <td>{{ idx }}</td>

                <td style="text-align: center;">
                    {% set item_doc = frappe.get_doc("Item", item_code) %}
                    {% for bc in item_doc.barcodes %}
                        {% if bc.uom in data.uoms %}
                            {{ bc.barcode }}{% if not loop.last %}<br>{% endif %}
                        {% endif %}
                    {% endfor %}
                </td>

                <td style="text-align: center;">
                    <strong>{{ data.item_name }}</strong>
                </td>

                <td style="text-align: center;">
                    {% for uom, qty in data.uoms.items() %}
                        {{ qty }} {{ uom }}{% if not loop.last %}, {% endif %}
                    {% endfor %}
                </td>
            </tr>
            {% set idx = idx + 1 %}
        {% endfor %}

        {# ---------------- TOTAL ROW ---------------- #}
        <tr style="border: 3px solid {{ color }}; font-weight: bold; background: #f2f2f2;">
            <td colspan="3" style="text-align: center;">Total Quantity</td>
            <td style="text-align: center;">
                {% for uom, qty in uom_totals.items() %}
                    {{ qty }} {{ uom }}{% if not loop.last %}, {% endif %}
                {% endfor %}
            </td>
        </tr>

        </tbody>
    </table>

    <!-- ======================================================================= -->
    <!-- ======================= PAYMENT TERMS TABLE ============================ -->
    <!-- ======================================================================= -->

    {% if doc.payment_schedule %}
        <p class="pf-label">Payment Terms</p>

        <table class="pf-item-table pf-font-size" style="width:100%; border:3px solid {{ color }}; border-collapse:collapse;">
            <thead>
            <tr style="background-color:{{ color }}; color:white;">
                <th>Payment Term</th>
                <th>Due Date</th>
                <th>Invoice Portion (%)</th>
                <th>Payment Amount</th>
            </tr>
            </thead>

            <tbody>
            {% for p in doc.payment_schedule %}
                <tr style="border:1px solid {{ color }};">
                    <td style="padding:6px; text-align:center;">{{ p.payment_term }}</td>
                    <td style="padding:6px; text-align:center;">{{ p.get_formatted("due_date") }}</td>
                    <td style="padding:6px; text-align:center;">{{ p.invoice_portion }}</td>
                    <td style="padding:6px; text-align:center;">{{ p.get_formatted("payment_amount") }}</td>
                </tr>
            {% endfor %}
            </tbody>
        </table>
    {% endif %}

    {% if doc.terms %}
        <div>
            <p><strong class="pf-color">Terms and conditions</strong></p>
            <br>
            <p>{{ doc.terms }}</p>
        </div>
    {% endif %}

    {% if footer %}
        <div class="text-center footer small">
            {{ footer }}
        </div>
    {% endif %}

</div>


{% set workflow_signatures = get_workflow_signatures_for_print(doc.doctype, doc.name) %}

{% if workflow_signatures and workflow_signatures|length > 0 %}
    <div style="width:100%; border-top:2px solid black; margin-top:30px; margin-bottom:10px;"></div>

    <div style="display:flex; justify-content:space-around; align-items:flex-start; flex-wrap:wrap; text-align:center;">
        {% for step in workflow_signatures %}
            <div style="margin:10px 20px;">
                <div style="font-size:14px; font-weight:bold; margin-bottom:10px;">
                    {{ step.user }}
                </div>
                {% if step.signature %}
                    <img src="{{ step.signature }}"
                         style="max-width:150px; max-height:80px; height:auto; width:auto; object-fit:contain;">
                {% else %}
                    <div style="height:80px; width:150px; border:1px dashed #ccc; display:flex; align-items:center; justify-content:center; font-size:11px;">
                        No Signature
                    </div>
                {% endif %}
            </div>
        {% endfor %}
    </div>
{% else %}
    <p style="margin-top:30px;"><strong>No workflow signatures found.</strong></p>
{% endif %}
